Define  
    \marginpar{
        \raggedright
        \emph{-- \nolinebreak\ifx&$l$, $r$, $m$, $R$, $C$, $T$, $CT$&{$l, r : \mathcal A_{2}^{\ge 1} \to \mathcal A_{2}^*, m : \mathcal A_{2}^{\ge 2} \to \mathcal A_{2}^*, R, C : \mathcal A_{2}^* \to \mathcal A_{2}^*, T, CT : \mathbb N \to \mathcal A_{2}^*$}\else{$l$, $r$, $m$, $R$, $C$, $T$, $CT$}\fi}
    } 
    \emph{$l, r : \mathcal A_{2}^{\ge 1} \to \mathcal A_{2}^*, m : \mathcal A_{2}^{\ge 2} \to \mathcal A_{2}^*, R, C : \mathcal A_{2}^* \to \mathcal A_{2}^*, T, CT : \mathbb N \to \mathcal A_{2}^*$} 
 by
    \begin{align*}
        l \p w &= w_{[0, \# w - 1)}
    \\
        r \p w &= w_{[1, \# w)}
    \\
        m &= l \circ r
    \\ 
        R \p{w_0 \dots w_{\#w-1}} &= w_{\#w-1} \dots w_0
    \\
        C \p{w_0 \dots w_{\#w-1}} 
        &= C \p{w_0} \dots C \p{w_{\#w-1}}
        \text{, where } C \p \bm 0 = \bm 1 \land C \p \bm 1 = \bm 0
    \\ 
        T^n &= 
        \begin{cases}
            \upepsilon & \text{if } n = 0
        \\
            T^{n-1} \bm 0 & \text{if } n \text{ odd}
        \\
            T^{n-1} \bm 1 & \text{if } n \text{ even} > 0
        \end{cases}            
    \\
        CT^n &= C \p {T^n}.
    \end{align*}

\begin{align}
        l \circ r &= r \circ l
        \label{eq:lrrl}
    \\ 
        l \circ m = m \circ l &\land 
        r \circ m = m \circ r
        \label{eq:lmmlrmmr}
    \\
        R \circ l = r \circ R &\land 
        R \circ r = l \circ R
        \label{eq:RlrRRrlR}
    \\ 
        R \circ m &= m \circ R
        \label{eq:RmmR}
    \\             
        C \circ l = l \circ C &\land 
        C \circ r = r \circ C
        \label{eq:CllCCrrC}
    \\ 
        C \circ m &= m \circ C
        \label{eq:CmmC}
    \\ 
        R \circ C &= C \circ R
        \label{eq:RCCR}
    \end{align}

\marginpar{
        \raggedright
        \emph{-- \nolinebreak\ifx&the function $\xi$&{$\xi$}\else{the function $\xi$}\fi}
    } 
    \emph{$\xi$} 
$: \mathcal A_{2}^* \to  \crl{-1, 0, 1}$ is defined recursively by \nopagebreak
    \begin{align*}
        \xi\p w &= 
        \begin{cases}
            0  & \text{if } w = \upepsilon
        \\
            1  & 
            \text{if } w \in \crl T ^ {\mathrm{even} \ge 0}
        \\ 
            -1  & 
            \text{if } w \in \crl {CT} ^ {\mathrm{even} \ge 0}
        \\
            \operatorname{sgn} \p{\xi \p{l \p w} + \xi \p{r \p w}} & \text{else}.
        \end{cases}
    \end{align*}

\label{lemma:xiCxiR}
    \begin{align}
        \xi \circ C = \xi \circ R = -\xi 
        \label{eq:xiCxiR}
    \end{align}

\label{corll:xipalindrome}
    Let $w \in \mathcal A_{2}^*$ be a palindrome. Then 
    \begin{align}
        \xi \p w = 0
        \label{eq:xipalindrome}.        
    \end{align}

\label{corll:xiTodd}
    Let $k$ be odd. Then 
    \begin{align}
        \xi \p{T^k} = 
        \xi \p{CT^k} = 
        0.
        \label{eq:xiTodd}
    \end{align}

\label{observ:xi0} 
    Let $w \in \mathcal A_{2}^{\ge 1}$.
    \begin{align}
        \xi \p w = 0 &\iff
        w \notin \crl{T}^\mathrm{even} \cup \crl{CT}^\mathrm{even} \land
        \xi \p{l \p w} = -\xi \p{r \p w}
        \label{eq:xi0}
    \end{align}

Let $w \in \mathcal A_{2}^{\ge 1}$ such that $\xi \p{l \p w}, \xi \p{r \p w} \ne 0$. Then
    \begin{align}
        \xi \p w = 0 \iff
        \xi \p{l \p w} \ne \xi \p{r \p w}
        \label{eq:xi0*}
    \end{align}

\label{lemma:xixil} \label{lemma:xixir}
    Let $w \in \mathcal A_{2}^{\ge 1}$ such that $\xi \p{w} \ne 0$. Then 
    \begin{align}
        \xi \p{l \p{w}} \ne 0 &\implies
        \xi \p{w} = \xi \p{l \p w}
        \label{eq:xixir}
    \\ 
        \xi \p{r \p{w}} \ne 0 &\implies
        \xi \p{w} = \xi \p{r \p w}
        \label{eq:xixil}.
    \end{align}

\label{lemma:xi0i1j}
    Let $\imath, \jmath \ge 1$. Then 
    \begin{align}
        \xi \p{\bm 0^\imath \bm 1^\jmath} = 1.
        \label{eq:xi0i1j}
    \end{align}

\label{corll:xi1j0i}
    \begin{align}
        \xi \p{\bm 1^\jmath \bm 0^\imath} = -1
        \label{eq:xi1j0i}
    \end{align}

\label{lemma:xiTk0}
    Let $k \ge 2$. Then 
    \begin{align}
        \xi \p{T^k \bm 0} &= 
        \begin{cases}
             0 & \text{if } k 
    \text{ is even{{}}}

        \\ 
            -1 & \text{if } k 


    \makebox[\widthof{$
    \text{ is even{{}}}
{}$}][l]{$\text{ is odd{{}}}$}



        \end{cases}
        \label{eq:xiTk0}
    \\
        \xi \p{T^k \bm 1} &= 1
        \label{eq:xiTk1}
    \\            
        \xi \p{CT^k \bm 0} &= -1
        \label{eq:xiCTk0}
    \\
        \xi \p{CT^k \bm 1} &= 
        \begin{cases}
            0 & \text{if } k 
    \text{ is even{{}}}

        \\ 
            1 & \text{if } k 


    \makebox[\widthof{$
    \text{ is even{.}}
{}$}][l]{$\text{ is odd{.}}$}



        \label{eq:xiCTk1}
        \end{cases}
    \end{align}

\label{lemma:xilr0}
    \label{lemma:inequalityproof}
    Let $w \in \mathcal A_{2}^{\ge 1}$ such that $\xi \p{l \p w} = \xi \p{r \p w} = 0$. Then 
    \begin{align}
        \xi \p w = 

    \makebox[\widthof{$-1$}][r]{$0$}

 &\implies 
        w \in \crl \bm 0 ^* \cup \crl \bm 1 ^*
        \label{eq:xilr0xi0}
    \\ 
        \xi \p w = 

    \makebox[\widthof{$-1$}][r]{$1$}

 &\implies 
        w \in \crl{ T}^\mathrm{even}
        \label{eq:xilr0xi1}
    \\ 
        \xi \p w = -1 &\implies 
        w \in \crl{CT}^\mathrm{even}  
        \label{eq:xilr0xim1}.
    \end{align}

\label{lemma:xi0xim0}
    Let $w \in \mathcal A_{2}^{\ge 2}$ such that $\xi \p w = 0$. Then 
    \begin{align}
        \xi \p{m \p w} = 0
        \label{eq:xi0xim0}.
    \end{align}

\label{thrm:ximne0}
    Let $w \in \mathcal A_{2}^{\ge 2}$ such that $\xi \p{l^2 \p w} = \xi \p{r^2 \p w} \ne 0$. Then 
    \begin{align}
        \xi \p{m \p w} \ne 0.
        \label{eq:xillxirrxim0}
    \end{align}

\label{lemma:ximw0w}
    Let $n \ge 2, w \in \mathcal A_{2}^n$ such that $\xi \p{m \p w} = 0$. Then 
    \begin{align}
        &\xi \p{l \p w} = 
        \xi \p{r \p w} = 


    \makebox[\widthof{$-1$}][r]{$0$}

 \iff 
        w \in \crl{\bm 0^n, \bm 1^n} 
        \label{eq:ximw0w0n1n}
    \\ 
        &\xi \p{l \p w} = 
        \xi \p{r \p w} = 


    \makebox[\widthof{$-1$}][r]{$1$}

 \iff 
        w \in \crl{
            \bm 0 T^{n-1},
            T^{n-1} \bm 1
        } \land 
        n 


    \makebox[\widthof{$
    \text{ is even{{}}}
{}$}][l]{$\text{ is odd{{}}}$}



        \label{eq:ximw0w0Tn1Tn11}
    \\         
        &\xi \p{l \p w} = \xi \p{r \p w} = -1 \iff 
        w \in \crl{
            CT^{n-1} \bm 0,
            \bm 1 CT^{n-1}
        } \land 
        n 


    \makebox[\widthof{$
    \text{ is even{{}}}
{}$}][l]{$\text{ is odd{{}}}$}



        \label{eq:ximw0wCTn101CTn1}
    \\ 
        &\xi \p{l \p w} = 

    \makebox[\widthof{$-1$}][r]{$0$}

 \land 
        \xi \p{r \p w} = 

    \makebox[\widthof{$-1$}][r]{$1$}

 \iff 
        w = \bm 0^{n-1} \bm 1
        \label{eq:ximw0w0n11}
    \\ 
        &\xi \p{l \p w} = 

    \makebox[\widthof{$-1$}][r]{$0$}

 \land 
        \xi \p{r \p w} = -1 \iff 
        w = \bm 1^{n-1} \bm 0
        \label{eq:ximw0w1n10}
    \\ 
        &\xi \p{l \p w} = 

    \makebox[\widthof{$-1$}][r]{$1$}

 \land 
        \xi \p{r \p w} = 

    \makebox[\widthof{$-1$}][r]{$0$}

 \iff 
        w = \bm 0 \bm 1^{n-1}
        \label{eq:ximw0w01n1}
    \\ 
        &\xi \p{l \p w} = -1 \land 
        \xi \p{r \p w} = 

    \makebox[\widthof{$-1$}][r]{$0$}

 \iff 
        w = \bm 1 \bm 0^{n-1}
        \label{eq:ximw0w10n1}.
    \end{align}

\label{thrm:existsxineg}
    Let $k, n \in \mathbb N$ and $w \in \mathcal A_{2}^{k+n}$ be such that $$w_{\hopen{0, n}} = w_{\hopen{k, k+n}} \land \exists \imath < k \quad \xi \p{w_{\hopen{\imath, \imath+n}}} = 1.$$ Then 
    \begin{align*}
        \exists \jmath < k \quad 
        \xi \p{w_{\hopen{\jmath, \jmath+n}}} = -1.
    \end{align*}

\marginpar{
        \raggedright
        \emph{-- \nolinebreak\ifx&the function $\phi$&{$\phi$}\else{the function $\phi$}\fi}
    } 
    \emph{$\phi$} 
$: \mathcal A_{2}^* \to  \crl{-1, 0, 1}$ is defined recursively by
    \begin{align*}
        \phi\p w &= 
        \begin{cases}
            0  & \text{if } w = \upepsilon
        \\
            -1  & 
            \text{if } w \in \crl \bm 0 ^ \mathrm{odd}
        \\ 
            1 & 
            \text{if } w \in \crl \bm 1 ^ \mathrm{odd}
        \\
            \operatorname{sgn} \p{\phi \p{r \p w} - \phi \p{l \p w}} & \text{else}.
        \end{cases}
    \end{align*}

\begin{align}
        \phi \circ C &= -\phi &
        \p{\phi \circ R} \p w&= 
        \p{-1}^{\# w + 1} \cdot \phi \p w 
        \label{eq:phiCphiR}
    \end{align}

\label{corll:phipalindrome}
    Let $w \in \mathcal A_{2}^\mathrm{even}$ be a palindrome. Then 
    \begin{align*}
        \phi \p w = 0.       
    \end{align*}

\label{corll:phi01even}
    Let $k$ be even. Then 
    \begin{align}
        \phi \p{\bm 0^k} = 
        \phi \p{\bm 1^k} = 
        0
        \label{eq:phi01even}
    \end{align}

\label{observ:phi0}
    Let $w \in \mathcal A_{2}^{\ge 1}$.
    \begin{align}
        \phi \p w = 0 &\iff 
        w \notin \crl \bm 0 ^\mathrm{odd} \cup \crl \bm 1 ^\mathrm{odd} \land 
        \phi \p{l \p w} = \phi \p{r \p w}
        \label{eq:phi0}
    \end{align}

Let $w \in \mathcal A_{2}^{\ge 1}$ such that $\phi \p{l \p w}, \phi \p{r \p w} \ne 0$. Then
    \begin{align}
        \phi \p w = 0 \iff 
        \phi \p{l \p w} = \phi \p{r \p w}
        \label{eq:phi0*}
    \end{align}

\label{lemma:phiphir}
    Let $w \in \mathcal A_{2}^{\ge 1}$ such that $\phi \p{w} \ne 0$. Then 
    \begin{align}
        \phi \p{r \p{w}} \ne 0 &\implies
        \phi \p{w} = \phi \p{r \p w}
        \label{eq:phiphir}
    \\ 
        \phi \p{l \p{w}} \ne 0 &\implies
        \phi \p{w} \ne \phi \p{l \p w}
        \label{eq:phiphil}.
    \end{align}

\label{lemma:phi0i1j}
    Let $\imath, \jmath \ge 1$. Then 
    \begin{align}
        \phi \p{\bm 0^\imath \bm 1^\jmath} = \p{-1}^{\jmath+1}.
        \label{eq:phi0i1j}
    \end{align}

\label{corll:phi1j0i}
    \begin{align*}
        \phi \p{\bm 1^\jmath \bm 0^\imath} = \p{-1}^{\imath}

    \end{align*}

\label{lemma:philwrw0}
    $$
        \forall w \in \mathcal A_{2}^{\ge 1} \quad 
        \phi \p{l \p w} = \phi \p{r \p w} = 0 \implies
        w \in \crl \bm 0 ^\mathrm{odd} \cup \crl \bm 1 ^\mathrm{odd}
    $$

\label{lemma:phimw0}
    Let $w \in \mathcal A_{2}^{\ge 2}$ such that $\phi \p w = 0$. Then 
    \begin{align}
        \phi \p{m \p w} = 0
        \label{eq:phimw0}.
    \end{align}

\label{corll:phiodd}
    Let $w \in \mathcal A_{2}^{\mathrm{odd}}$. Then 
    \begin{align}
        \phi \p w \ne 0
        \label{eq:phiodd}.
    \end{align}

\label{lemma:phimne0}
    Let $w \in \mathcal A_{2}^{\ge 2}$ such that $\phi \p{l^2 \p w} = \phi \p{r^2 \p w} \ne 0$. Then 
    \begin{align*}
        \phi \p{m \p w} \ne 0.
    \end{align*}

\label{lemma:phimw0w}
    Let $w \in \mathcal A_{2}^2$ such that $\phi \p{m \p w} = 0$. Then 
    \begin{align*}
        \phi \p w \ne 0 \iff 
        w \in \Lambda^{\ge 2} = 
        \bigcup_{n \ge 1} \crl{
            \bm 0^n \bm 1, 
            \bm 0 \bm 1^n, 
            \bm 1 \bm 0^n, 
            \bm 1^n \bm 0
        }.
    \end{align*}

\label{lemma:phimwximw0}
    Let $w \in \mathcal A_{2}^{\ge 2}$ such that $\phi \p{m \p w} = \xi \p{m \p w} = 0$. Then 
        \begin{align}
            \phi \p w = \xi \p w
            \label{eq:phimwximw0}.
        \end{align}

\label{thrm:phi0xi0}
    Let $w \in \mathcal A_{2}^*$. 
    \begin{align}
        \phi \p w = 0 \iff 
        \# w 
    \text{ is even{{}}}
 \land \xi \p w = 0
        \label{eq:phi0xi0}
    \end{align}

\label{corll:philphir}
    Let $w \in \mathcal A_{2}^{\ge 1}$ be such that $\xi \p{l \p w}, \xi \p{r \p w} \ne 0$. 
    Then 
    \begin{align}
        \phi \p{l \p w} = \phi \p{r \p w} \iff 
        \# w 
    \text{ is even{{}}}
 \land 
        \xi \p{l \p w} \ne \xi \p{r \p w}
        \label{eq:philphir}
    \end{align}

\label{lemma:phillphirr}
    Let $w \in \mathcal A_{2}^{\ge 2}$ such that 
    \begin{align}
        \xi \p{l^2 \p w}, \xi \p{r^2 \p w} \ne 
        0 = 
        \xi \p{m \p w}
        \label{eq:cond:phillphirrxim0}.
    \end{align}
    Then 
    \begin{align}
        \phi \p{l^2 \p w} = 
        \phi \p{r^2 \p w} \iff
        \# w 


    \makebox[\widthof{$
    \text{ is even{{}}}
{}$}][l]{$\text{ is odd{{}}}$}



        \label{eq:phillphirr}.
    \end{align}

\label{lemma:philllphirrr}
    Let $k, n \in \mathbb N, w \in \mathcal A_{2}^\mathbb N$ such that $k \ge 1$ and 
    \begin{align*}
        \forall \jmath \le k \quad \p{
            \xi \p{w_{\hopen{\jmath, \jmath+n}}} \ne 0 \iff
            \jmath \in \crl{0, k}
        }.
    \end{align*}
    Then 
    \begin{align}
        \phi \p{w_{\hopen{0, n}}} = 
        \phi \p{w_{\hopen{k, k+n}}} \iff 
        n 


    \makebox[\widthof{$
    \text{ is even{{}}}
{}$}][l]{$\text{ is odd{{}}}$}


 \land 
        \xi \p{w_{\hopen{0, n}}} \ne 
        \xi \p{w_{\hopen{k, k+n}}}
        \label{eq:philllphirrr}.
    \end{align}

Define $\psi: \mathcal A_{2}^* \to \crl{-1, 0, 1}$ by
    \begin{align}        
        \psi \p w 
        &= \p{\xi \p w}^{\# w} \cdot \phi \p w
        \label{eq:psi}.
    \end{align}
    $\psi$ is called the  
    \marginpar{
        \raggedright
        \emph{-- \nolinebreak\ifx&alternating colouring function~$\psi$&{alternating colouring function}\else{alternating colouring function~$\psi$}\fi}
    } 
    \emph{alternating colouring function} 
. 

    $w \in \mathcal A_{2}^*$ is called  
    \marginpar{
        \raggedright
        \emph{-- \nolinebreak\ifx&colourable string&{colourable}\else{colourable string}\fi}
    } 
    \emph{colourable} 
 if $\psi \p w \ne 0$. 
    For $n \ge 2$ the sft{} generated by prohibiting the strings in $\crl{w \in \mathcal A_{2}^n; \psi \p w = 0}$ is called the  
    \marginpar{
        \raggedright
        \emph{-- \nolinebreak\ifx&{}&{maximal $n$"~colourable shift}\else{{}}\fi}
    } 
    \emph{maximal $n$"~colourable shift} 
. 
    Any subshift of the maximal $n$"~colourable shift is called  
    \marginpar{
        \raggedright
        \emph{-- \nolinebreak\ifx&$n$-colourable shift&{$n$"~colourable}\else{$n$-colourable shift}\fi}
    } 
    \emph{$n$"~colourable} 
.

\begin{align}
        \p{\psi \circ C} \p w = 
        \p{-1}^{\# w + 1} \cdot \psi \p w &&
        \psi \circ R = -\psi 
        \label{eq:psiCpsiR}
    \end{align}

\label{lemma:psi0xi0}
    Let $w \in \mathcal A_{2}^*$. Then
    \begin{align}
        \psi \p w = 0 \iff \xi \p w = 0
        \label{eq:psi0xi0}.
    \end{align}

Let $w \in \mathcal A_{2}^\mathrm{even}$. Then 
    \begin{align}
        \psi \p w = \phi \p w.
        \label{eq:psiphi}
    \end{align}

\label{thrm:psilllpsirrr}
    Let $k, n \in \mathbb N, w \in \mathcal A_{2}^\mathbb N$ such that $k \ge 1$ and 
    \begin{align*}
        w_{\hopen{\jmath, \jmath+n}} \text{ is colourable} \iff
        \jmath \in \crl{0, k}.
    \end{align*}
    Then 
    \begin{align}
        \psi \p{w_{\hopen{0, n}}} \ne 
        \psi \p{w_{\hopen{k, k+n}}}
        \label{eq:psilllpsirrr}.
    \end{align}

\label{corll:psilpsir}      
    Let $w \in \mathcal A_{2}^{\ge 1}$ be such that $l \p w, r \p w$ are colourable. 
    Then $\psi \p{l \p w} \ne \psi \p{r \p w}$.

\label{corll:psialtersz}
    Let $k, n \in \mathbb N, w \in \mathcal A_{2}^\mathbb N$ such that ${w_{\hopen{0, n}}}, {w_{\hopen{k, k+n}}}$ are colourable. Set $$z = \# \crl{\jmath < k; w_{\hopen{\jmath, \jmath + n}} \text{ is not colourable}}.$$ Then 
    \begin{align}
        \psi \p{w_{\hopen{k, k+n}}} = 
        \p{-1}^{k-z} \cdot \psi \p{w_{\hopen{0, n}}}
        \label{eq:psialtersz}.
    \end{align}

Take $k, n, w, z$ as in corollary~\ref{corll:psialtersz}. 

    Let $\psi \p{w_{\hopen{0, n}}} = \psi \p{w_{\hopen{k, k+n}}}$. Then 
    \begin{align*}
        k 
    \text{ is even{{}}}
 \iff 
        z 
    \text{ is even{.}}

    \end{align*}

\label{corll:psialters}
    Let $n \in \mathbb N$ and $w$ be a point in an $n$"~colourable shift. Then 
    \begin{align}
        \forall k \in \mathbb N \quad 
        \psi \p{w_{[k, k+n)}} = 
        \p{-1}^{k} \cdot \psi \p{w_{[0, n)}}
        \label{eq:psialters}.
    \end{align}

Let $n \ge 4$. Then 
    \begin{align}
        \#\crl{
            w \in \mathcal A_{2}^n; \xi \p{m \p w} = 0 \land \xi \p w \ne 0
        } = 
        6 - 2 \cdot \p{-1}^{n}
        \label{eq:hashxm0xn0}
    \end{align}

\label{corll:KnKn2}
    For $n \in \mathbb N$ set $K_n = \# \crl{w \in \mathcal A_{2}^n; \psi \p w = 0}$. Let $n \ge 4$. Then 
    \begin{align}
        K_n = 
        4 \cdot K_{n-2} - 6 + 2 \cdot \p{-1}^{n}.
        \label{eq:KnKn2}
    \end{align}

For $n \in \mathbb N$ the  
    \marginpar{
        \raggedright
        \emph{-- \nolinebreak\ifx&{}&{Jacobsthal number}\else{{}}\fi}
    } 
    \emph{Jacobsthal number} 
 $J_n$ is defined as 
    \begin{align}
        J_n = \frac{2^n - \p{-1}^{n}}{3}
        \label{eq:Jn}.
    \end{align}

\label{fact:Jn12}
    Let $n \in \mathbb N$. 
    \begin{align}
        J_{n+1} &= 
        2 \cdot J_{n} + \p{-1}^{n} 
        \label{eq:Jn1}
    \\       
        J_{n+2} &=  
        J_{n+1} + 2 \cdot J_n
        \label{eq:Jn2}
    \end{align}

\label{thrm:Kn2}
    Let $n \in \mathbb N$. 
    \begin{align}
        K_{n+2} = 2 \cdot \p{J_n + 1}. 
        \label{eq:Kn2}
    \end{align}

\label{corll:Kn}
    Let $n \ge 2$. Then 
    \begin{align}
        n 
    \text{ is even{{}}}
 \implies&
        K_n = \frac{2^n + 

    \makebox[\widthof{$16$}][r]{$8$}

}{6}
        \label{eq:Kneven}
    \\ 
        n 


    \makebox[\widthof{$
    \text{ is even{{}}}
{}$}][l]{$\text{ is odd{{}}}$}


  \implies&
        K_n = \frac{2^n + 16}{6}
        \label{eq:Knodd}.
    \end{align}

\label{corll:Kn1Kneven}
    Let $n$ be even. Then 
